/* Tech IA · unitat 3 «Parlar amb models de llenguatge» (i3-1 … i3-4)
   Contingut propi de Numi. Com funciona un xatbot per dins (model gran que prediu fitxes, ajust com a assistent,
   finestra de context, eines i data de tall: i3-1); al·lucinacions, fonts inventades i com comprovar-les (i3-2); bons
   prompts: context, tasca, format, exemple, límits i comprovació, i iterar (i3-3); i el projecte de la IA com a tutora i
   no com a copiadora, amb normes d'honestedat, edat i privadesa (i3-4). Tota la IA és simulada (iachat i iaprompt); la IA
   en directe només surt si el docent l'ha activada. Persones, apps, llibres, instituts i volcans: inventats. */
Object.assign(TBADGE, {
  i_llm: { id: 'i_llm', ico: '🧠', n: 'Mecànic/a de xatbots|Mecánico/a de chatbots', d: "Has descobert què hi ha dins d'un xatbot: fitxes, finestra de context, ajust com a assistent i eines.|Has descubierto qué hay dentro de un chatbot: fichas, ventana de contexto, ajuste como asistente y herramientas." },
  i_hunt: { id: 'i_hunt', ico: '🚩', n: "Caçador/a d'al·lucinacions|Cazador/a de alucinaciones", d: "Has caçat dades, fonts i cites inventades per una IA i les has sabut comprovar.|Has cazado datos, fuentes y citas inventadas por una IA y has sabido comprobarlas." },
  i_prompt: { id: 'i_prompt', ico: '✍️', n: 'Mestre/a del prompt|Maestro/a del prompt', d: "Has escrit prompts amb context, tasca, format, exemple, límits i comprovació, i els has millorat iterant.|Has escrito prompts con contexto, tarea, formato, ejemplo, límites y comprobación, y los has mejorado iterando." },
  i_tutor: { id: 'i_tutor', ico: '🧑‍🏫', n: 'Estudi amb cap|Estudio con cabeza', d: "Has dissenyat i provat una rutina per estudiar amb IA que et fa pensar, amb normes d'honestedat i privadesa.|Has diseñado y probado una rutina para estudiar con IA que te hace pensar, con normas de honestidad y privacidad." }
});

