  count: [{ k: 'run', act: [{ click: '#btn' }, { click: '#btn' }, { click: '#btn' }], see: { sel: '#count', text: '3' }, txt: 'Prova: amb 3 clics, el número diu 3|Prueba: con 3 clics, el número dice 3' }],
