  timer: [{ k: 'run', act: [{ click: '#start' }, { wait: 3300 }, { click: '#box' }], see: { sel: '#time', text: '/ms/' }, txt: 'Prova: en 3 segons ja es pot tocar i surt el temps|Prueba: en 3 segundos ya se puede tocar y sale el tiempo' }],
