  theme: [{ k: 'run', act: [{ click: '#theme' }, { click: '#theme' }], see: { sel: 'body', cls: 'dark', not: true }, txt: 'Prova: tocant-lo dues vegades, torna a clar|Prueba: tocándolo dos veces, vuelve a claro' }],
